import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { AvatarOutfit } from '../utils/avatarOutfit';
import { isAppIdle } from '../utils/idleSleep';

// Share fetched model bytes across scene rebuilds (companion swaps
// rebuild this scene): a 20+ MB GLB is never downloaded twice just
// because the player changed companions.
THREE.Cache.enabled = true;

// Plain three.js stroll scene — deliberately NOT @react-three/fiber:
// fiber 9 (via `its-fine`) statically references React.use, which React 18
// does not export, so importing fiber breaks the production build.
// Plain three.js compiles and runs fine on React 18.
//
// Third-person walk: the player's avatar (a simple stylized humanoid
// built from primitives — see below) strolls with their navitar through
// a procedural Forest or City. WASD / arrow keys move, the thumb
// glide on the page does the same for touch, dragging orbits the camera around the
// walkers. Trees and buildings are visual only in v1 — there is NO
// collision — the walker is simply clamped to the ground bounds.
export type StrollEnvironment = 'forest' | 'city';

export interface StrollCompanion {
  name: string;
  element: string;
  modelUrl?: string;
  modelZoom?: number;
  // Resolved 2D art (look-picker pick, or the name map) — shown on a
  // billboard when the companion has no GLB.
  imageUrl?: string | null;
}

// Thumb glide (Round 8, Eddie 2026-11-16): while the player's thumb
// drags across the lower screen, the Stroll page writes the drag's
// screen-space vector here — each axis −1..1, x = right, y = DOWN
// (a thumb pulled down the screen reads +y). The scene turns it
// into travel: camera-relative outside AR, frame-relative in AR.
export interface GlideVector {
  x: number;
  y: number;
}

// Wild encounter (Round 13, Eddie 2026-11-17): a wild navitar that
// has popped up in the realm scene. The PAGE owns the encounter
// (spawn rolls on real travel, the Fight / Let it go card, the
// battle handoff); the scene only RENDERS it — the creature's real
// GLB standing on an element ring near the walker, with a pop-in
// entrance. Pool entries always carry a modelUrl (src/data/wild.ts:
// every wild's portrait is a modeled hero's portrait), so the scene
// never fakes a creature — if the GLB fails to load, nothing stands
// in the scene and the failure is marked on the mount dataset; the
// page's card (real portrait art) still names the encounter honestly.
export interface StrollWildEncounter {
  name: string;
  element: string;
  modelUrl: string;
  modelZoom?: number;
  modelRotationY?: number;
}

export type StrollWalkerKind = 'navitar' | 'avatar';

export interface GpsTarget {
  x: number;
  z: number;
  heading: number;
}

interface StrollSceneProps {
  environment: StrollEnvironment;
  companion: StrollCompanion | null;
  // AR camera mode (Step 6, Eddie 2026-11-14): the page owns the
  // camera stream and renders it UNDER this canvas; in AR the scene
  // goes transparent, the environment hides, and the companion
  // stands in a small fixed frame in front of the camera. The walker
  // in AR is ALWAYS the companion's real 3D model (the page only
  // enables AR when the companion has one — no billboards in AR).
  arMode: boolean;
  // Device-orientation parallax for AR: the page writes the latest
  // tilt here (radians-ish, small); the scene nudges the fixed AR
  // camera by it. Never gated on motion permissions — where the
  // browser never fires the event, the offset simply stays zero.
  parallax: React.MutableRefObject<{ x: number; y: number }>;
  // Called when a walker/companion GLB FAILS to load while AR is on
  // (or AR is switched on after a failure): AR never shows the 2D
  // card, so the page swaps in its honest no-model panel instead.
  onModelLoadError?: () => void;
  // Who walks: the player's navitar (Eddie, 2026-11-13 — "I would like
  // to walk in my character") or the dress-up avatar. The navitar is
  // the default whenever the player has one.
  walkerKind: StrollWalkerKind;
  // "Walk with me" GPS: the page owns the geolocation watch and
  // writes the latest world-space target here; the scene steers the
  // walker to it. COSMETIC ONLY — nothing in the scene reads or
  // writes venue check-in, presence, or any networking state.
  gpsTarget: React.MutableRefObject<GpsTarget | null>;
  // Thumb glide: the page owns the gesture (an overlay on the lower
  // screen) and writes the live vector here; null = no thumb down.
  glideRef: React.MutableRefObject<GlideVector | null>;
  // The player's current outfit (see src/utils/avatarOutfit.ts). The
  // scene applies it to the walker live — swapping outfits never
  // rebuilds the scene.
  outfit: AvatarOutfit;
  // Walk-training distance (Round 9, Eddie 2026-11-16: "stroll is
  // supposed to be a real thing here where you walk and train with
  // your navitar"): the scene accumulates the walker's real stepped
  // travel (world units) into this ref; the page converts it to
  // care XP/bond for the companion. Scene-local total — a scene
  // rebuild (companion swap) restarts it at 0 and the page
  // rebaselines, so a remount can never mint phantom distance.
  distanceRef?: React.MutableRefObject<number>;
  // Wild encounter (Round 13): the wild navitar currently popped up
  // in the scene, or null. Applied through the scene api (like the
  // environment/outfit/AR switches) so a spawn or despawn NEVER
  // rebuilds the scene — the walker's position and the training
  // distance survive an encounter untouched.
  encounter?: StrollWildEncounter | null;
  // Stroll compass (Round 33.5): the walker's live pose in scene
  // units, written every frame beside the dataset.walkerPos witness
  // (heading = walkerRoot.rotation.y). The page's compass reads it
  // on its own interval — held in a ref, never stored, never sent.
  // Optional: surfaces without a compass omit it.
  walkerRef?: React.MutableRefObject<{ x: number; z: number; heading: number } | null>;
  // Stroll compass (Round 33.5): the live encounter's standing
  // position in scene units, written by applyEncounter (null when
  // no encounter stands) — the ref twin of dataset.encounterPos.
  encounterPosRef?: React.MutableRefObject<{ x: number; z: number } | null>;
}

// World size (wave 4, Eddie 2026-11-13: "guide him through
// anywhere"): the ground is 3x the original 60 units (180 across)
// and the walkable bound is 3x the original 28 (84). Inside
// SOFT_BOUND movement is free; between SOFT_BOUND and BOUND it
// progressively resists (down to a crawl at the edge) and the fog
// swallows the boundary, so the world fades out instead of ending
// at a wall. The hard clamp at BOUND remains as a backstop.
const BOUND = 84;
const SOFT_BOUND = 74;
const WORLD = 180;
const WALK_SPEED = 4;
const TURN_SPEED = 2.4;

// Deterministic pseudo-random so the woods and the city look the same
// on every load (no layout jumps between visits).
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const ELEMENT_COLORS: Record<string, string> = {
  ice: '#81D4FA',
  fire: '#FF5722',
  nature: '#4CAF50',
  shadow: '#9C27B0',
  light: '#FFC107',
  quantum: '#B388FF',
  electric: '#FFEA00',
  spiritual: '#80DEEA',
  water: '#2196F3',
};

// A small canvas sprite that floats above the walker so the player can
// always tell which figure is them.
function makeTextSprite(text: string): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 72;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.font = 'bold 44px Roboto, Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineWidth = 8;
    ctx.strokeStyle = 'rgba(0,0,0,0.75)';
    ctx.strokeText(text, 128, 36);
    ctx.fillStyle = '#ffffff';
    ctx.fillText(text, 128, 36);
  }
  const texture = new THREE.CanvasTexture(canvas);
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(1.5, 0.42, 1);
  return sprite;
}

// Facade texture for the city buildings: dark dusk face with a grid of
// windows, some lit warm. Used as both the colour map and the emissive
// map, so the lit windows glow against the dusk.
function makeFacadeTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    const rng = mulberry32(99);
    ctx.fillStyle = '#232733';
    ctx.fillRect(0, 0, 128, 256);
    for (let row = 0; row < 12; row++) {
      for (let col = 0; col < 6; col++) {
        const lit = rng() < 0.45;
        ctx.fillStyle = lit ? '#ffca7a' : '#11141d';
        ctx.fillRect(8 + col * 20, 10 + row * 20, 12, 12);
      }
    }
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const StrollScene: React.FC<StrollSceneProps> = ({
  environment,
  companion,
  outfit,
  walkerKind,
  gpsTarget,
  glideRef,
  distanceRef,
  arMode,
  parallax,
  onModelLoadError,
  encounter,
  walkerRef,
  encounterPosRef,
}) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const errCbRef = useRef(onModelLoadError);
  errCbRef.current = onModelLoadError;
  // Latest encounter, readable inside the scene-build effect (which
  // applies it at build end, the applyEnvironment/applyOutfit
  // pattern) without making the encounter part of the rebuild key.
  const encounterPropRef = useRef<StrollWildEncounter | null>(encounter ?? null);
  encounterPropRef.current = encounter ?? null;
  const apiRef = useRef<{
    setEnvironment: (env: StrollEnvironment) => void;
    setOutfit: (o: AvatarOutfit) => void;
    setArMode: (on: boolean) => void;
    setEncounter: (wild: StrollWildEncounter | null) => void;
  } | null>(null);

  // Rebuild the scene only when the companion changes (different model
  // or art); the environment toggle flips visibility without rebuilding.
  const companionKey = companion
    ? `${companion.name}|${companion.modelUrl ?? ''}|${companion.imageUrl ?? ''}|${companion.element}`
    : 'none';
  const sceneKey = `${companionKey}|${walkerKind}`;

  useEffect(() => {
    apiRef.current?.setEnvironment(environment);
  }, [environment]);

  useEffect(() => {
    apiRef.current?.setOutfit(outfit);
  }, [outfit]);

  useEffect(() => {
    apiRef.current?.setArMode(arMode);
  }, [arMode]);

  useEffect(() => {
    apiRef.current?.setEncounter(encounter ?? null);
  }, [encounter]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    // Non-null alias for the async loader callbacks + error handler
    // below (TS loses the narrowing inside nested functions).
    const mountEl: HTMLDivElement = mount;
    let raf = 0;
    let cancelled = false;
    let renderer: THREE.WebGLRenderer | null = null;
    let scene: THREE.Scene | null = null;
    let camera: THREE.PerspectiveCamera | null = null;
    let forest: THREE.Group | null = null;
    let city: THREE.Group | null = null;
    let hemi: THREE.HemisphereLight | null = null;
    let sun: THREE.DirectionalLight | null = null;

    try {
      // alpha: true from the start so AR mode can make the canvas
      // transparent without rebuilding the renderer; outside AR the
      // scene's own background colour covers every pixel anyway.
      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    } catch {
      return;
    }
    renderer.setClearColor(0x000000, 0);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    mount.appendChild(renderer.domElement);

    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(
      55,
      mount.clientWidth / Math.max(mount.clientHeight, 1),
      0.1,
      500
    );

    hemi = new THREE.HemisphereLight(0xbfdcff, 0x3f6b4a, 0.9);
    scene.add(hemi);
    sun = new THREE.DirectionalLight(0xfff2d9, 1.6);
    sun.position.set(8, 14, 6);
    scene.add(sun);
    const fill = new THREE.DirectionalLight(0xffffff, 0.35);
    fill.position.set(-6, 4, -6);
    scene.add(fill);

    // ---------- Forest: green ground, dirt path, instanced trees ----------
    forest = new THREE.Group();
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a7d44, roughness: 1 });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(WORLD, WORLD), groundMat);
    ground.rotation.x = -Math.PI / 2;
    forest.add(ground);
    const pathMat = new THREE.MeshStandardMaterial({ color: 0x8d6e63, roughness: 1 });
    const path = new THREE.Mesh(new THREE.PlaneGeometry(3, WORLD), pathMat);
    path.rotation.x = -Math.PI / 2;
    path.position.y = 0.01;
    forest.add(path);
    const rng = mulberry32(1234);
    const treeCount = 270;
    const trunkGeo = new THREE.CylinderGeometry(0.14, 0.22, 1.6, 6);
    const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5d4037, roughness: 1 });
    const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, treeCount);
    const coneGeo = new THREE.ConeGeometry(1.3, 3.4, 8);
    const coneMat = new THREE.MeshStandardMaterial({ color: 0x2e7d32, roughness: 1 });
    const cones = new THREE.InstancedMesh(coneGeo, coneMat, treeCount);
    const dummy = new THREE.Object3D();
    let placed = 0;
    let tries = 0;
    while (placed < treeCount && tries < 600) {
      tries++;
      const x = (rng() * 2 - 1) * BOUND;
      const z = (rng() * 2 - 1) * BOUND;
      if (Math.abs(x) < 3) continue; // keep the path clear
      if (Math.hypot(x, z - 8) < 5) continue; // keep the spawn clearing clear
      const s = 0.8 + rng() * 0.7;
      dummy.position.set(x, 0.8 * s, z);
      dummy.scale.setScalar(s);
      dummy.rotation.y = rng() * Math.PI * 2;
      dummy.updateMatrix();
      trunks.setMatrixAt(placed, dummy.matrix);
      dummy.position.y = (1.6 + 1.7) * s;
      dummy.updateMatrix();
      cones.setMatrixAt(placed, dummy.matrix);
      placed++;
    }
    trunks.count = placed;
    cones.count = placed;
    forest.add(trunks);
    forest.add(cones);
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x78909c, roughness: 1 });
    for (let i = 0; i < 24; i++) {
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(0.4 + rng() * 0.5), rockMat);
      const x = (rng() * 2 - 1) * 72;
      const z = (rng() * 2 - 1) * 72;
      if (Math.abs(x) < 3) continue;
      rock.position.set(x, 0.25, z);
      rock.rotation.set(rng() * 3, rng() * 3, 0);
      forest.add(rock);
    }
    scene.add(forest);

    // ---------- City: asphalt, road grid, instanced buildings, lamps ----------
    city = new THREE.Group();
    const asphalt = new THREE.Mesh(
      new THREE.PlaneGeometry(WORLD, WORLD),
      new THREE.MeshStandardMaterial({ color: 0x33373d, roughness: 1 })
    );
    asphalt.rotation.x = -Math.PI / 2;
    city.add(asphalt);
    const roadMat = new THREE.MeshStandardMaterial({ color: 0x232528, roughness: 1 });
    const roadZ = new THREE.Mesh(new THREE.PlaneGeometry(6, WORLD), roadMat);
    roadZ.rotation.x = -Math.PI / 2;
    roadZ.position.y = 0.01;
    city.add(roadZ);
    const roadX = new THREE.Mesh(new THREE.PlaneGeometry(WORLD, 6), roadMat);
    roadX.rotation.x = -Math.PI / 2;
    roadX.position.y = 0.01;
    city.add(roadX);
    const dashMat = new THREE.MeshStandardMaterial({ color: 0xd7c200, roughness: 1 });
    for (let i = -80; i <= 80; i += 5) {
      if (Math.abs(i) < 5) continue; // keep the crossroads clear
      const dashZ = new THREE.Mesh(new THREE.PlaneGeometry(0.25, 2), dashMat);
      dashZ.rotation.x = -Math.PI / 2;
      dashZ.position.set(0, 0.02, i);
      city.add(dashZ);
      const dashX = new THREE.Mesh(new THREE.PlaneGeometry(2, 0.25), dashMat);
      dashX.rotation.x = -Math.PI / 2;
      dashX.position.set(i, 0.02, 0);
      city.add(dashX);
    }
    const facade = makeFacadeTexture();
    const buildingMat = new THREE.MeshStandardMaterial({
      map: facade,
      emissiveMap: facade,
      emissive: new THREE.Color(0xffffff),
      emissiveIntensity: 0.55,
      color: 0x9aa7b8,
      roughness: 0.9,
    });
    const boxGeo = new THREE.BoxGeometry(1, 1, 1);
    boxGeo.translate(0, 0.5, 0);
    const buildingCount = 144;
    const buildings = new THREE.InstancedMesh(boxGeo, buildingMat, buildingCount);
    const cityRng = mulberry32(777);
    const bDummy = new THREE.Object3D();
    const bColor = new THREE.Color();
    let bPlaced = 0;
    let bTries = 0;
    while (bPlaced < buildingCount && bTries < 900) {
      bTries++;
      const x = (cityRng() * 2 - 1) * BOUND;
      const z = (cityRng() * 2 - 1) * BOUND;
      if (Math.abs(x) < 5.5 || Math.abs(z) < 5.5) continue; // keep the roads clear
      if (Math.hypot(x, z - 8) < 6) continue; // keep the spawn clearing clear
      const w = 4 + cityRng() * 2.5;
      const d = 4 + cityRng() * 2.5;
      const h = 3 + cityRng() * 9;
      bDummy.position.set(x, 0, z);
      bDummy.scale.set(w, h, d);
      bDummy.rotation.y = 0;
      bDummy.updateMatrix();
      buildings.setMatrixAt(bPlaced, bDummy.matrix);
      bColor.setHSL(0.58 + cityRng() * 0.06, 0.12, 0.45 + cityRng() * 0.2);
      buildings.setColorAt(bPlaced, bColor);
      bPlaced++;
    }
    buildings.count = bPlaced;
    city.add(buildings);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x37474f, roughness: 0.8 });
    const lampMat = new THREE.MeshStandardMaterial({
      color: 0xffca7a,
      emissive: new THREE.Color(0xffb74d),
      emissiveIntensity: 1.2,
    });
    for (let i = -84; i <= 84; i += 12) {
      if (Math.abs(i) < 5) continue;
      for (const [lx, lz] of [
        [4, i],
        [-4, i],
      ] as const) {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 3, 6), poleMat);
        pole.position.set(lx, 1.5, lz);
        city.add(pole);
        const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), lampMat);
        lamp.position.set(lx, 3.1, lz);
        city.add(lamp);
      }
    }
    scene.add(city);

    // ---------- The walker: the user's avatar, a simple stylized
    // humanoid built from primitives and labelled "You". It is a
    // customizable character, not a likeness of anyone — its outfit
    // (top colour, pants colour, hat) comes from the current outfit in
    // src/utils/avatarOutfit.ts and swaps live via setOutfit below.
    // PLACEHOLDER: when Eddie's DAZ avatar GLB arrives, this group
    // should be replaced by the loaded GLB — the same way the navitar
    // GLBs drop in below — keeping the same position, heading and bob.
    // The outfit system stays: it would then drive the GLB's materials
    // instead of these primitives.
    const walker = new THREE.Group();
    const skin = new THREE.MeshStandardMaterial({ color: 0xe8b98a, roughness: 0.8 });
    const topMat = new THREE.MeshStandardMaterial({
      color: new THREE.Color(outfit.topColor),
      roughness: 0.9,
    });
    const pantsMat = new THREE.MeshStandardMaterial({
      color: new THREE.Color(outfit.pantsColor),
      roughness: 0.9,
    });
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.5, 4, 10), topMat);
    body.position.y = 0.88;
    walker.add(body);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.18, 16, 12), skin);
    head.position.y = 1.48;
    walker.add(head);
    const hair = new THREE.Mesh(
      new THREE.SphereGeometry(0.19, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.55),
      new THREE.MeshStandardMaterial({ color: 0x3e2723, roughness: 1 })
    );
    hair.position.y = 1.5;
    walker.add(hair);
    // Hat / accessory slot: rebuilt whenever the outfit changes.
    const hatGroup = new THREE.Group();
    walker.add(hatGroup);
    const buildHat = (o: AvatarOutfit) => {
      while (hatGroup.children.length > 0) {
        const child = hatGroup.children[0];
        hatGroup.remove(child);
        const mesh = child as THREE.Mesh;
        if (mesh.geometry) mesh.geometry.dispose();
        const material = mesh.material as THREE.Material | undefined;
        if (material) material.dispose();
      }
      // A beanie covers the hair; a crown sits on top of it.
      hair.visible = o.hat !== 'beanie';
      if (o.hat === 'beanie') {
        const hatMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(o.hatColor),
          roughness: 1,
        });
        const cap = new THREE.Mesh(
          new THREE.SphereGeometry(0.2, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.62),
          hatMat
        );
        cap.position.y = 1.52;
        hatGroup.add(cap);
        const brim = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.035, 8, 20), hatMat);
        brim.rotation.x = Math.PI / 2;
        brim.position.y = 1.5;
        hatGroup.add(brim);
      } else if (o.hat === 'crown') {
        const gold = new THREE.MeshStandardMaterial({
          color: new THREE.Color(o.hatColor),
          metalness: 0.8,
          roughness: 0.3,
        });
        const band = new THREE.Mesh(
          new THREE.CylinderGeometry(0.18, 0.18, 0.09, 12, 1, true),
          gold
        );
        band.position.y = 1.66;
        hatGroup.add(band);
        for (let i = 0; i < 5; i++) {
          const angle = (i / 5) * Math.PI * 2;
          const point = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.09, 4), gold);
          point.position.set(Math.cos(angle) * 0.18, 1.75, Math.sin(angle) * 0.18);
          hatGroup.add(point);
        }
      }
    };
    buildHat(outfit);
    const armGeo = new THREE.CapsuleGeometry(0.07, 0.34, 4, 8);
    const leftArm = new THREE.Mesh(armGeo, topMat);
    leftArm.position.set(-0.32, 0.95, 0);
    walker.add(leftArm);
    const rightArm = new THREE.Mesh(armGeo, topMat);
    rightArm.position.set(0.32, 0.95, 0);
    walker.add(rightArm);
    const legGeo = new THREE.CapsuleGeometry(0.09, 0.36, 4, 8);
    const leftLeg = new THREE.Mesh(legGeo, pantsMat);
    leftLeg.position.set(-0.12, 0.32, 0);
    walker.add(leftLeg);
    const rightLeg = new THREE.Mesh(legGeo, pantsMat);
    rightLeg.position.set(0.12, 0.32, 0);
    walker.add(rightLeg);
    const youLabel = makeTextSprite('You');
    youLabel.position.y = 2.05;
    walker.add(youLabel);
    // The walker root carries position, heading and bob for WHOEVER
    // walks — the humanoid below, or the player's navitar.
    const walkerRoot = new THREE.Group();
    walkerRoot.position.set(0, 0, 8);
    scene.add(walkerRoot);
    walkerRoot.add(walker);

    // ---------- Walk as your navitar (Eddie, 2026-11-13: "I would
    // like to walk in my character") ---------- When walkerKind is
    // 'navitar', the player's own navitar IS the walker: its GLB when
    // it has one (the same box-grounded load the companion uses),
    // else its portrait on a camera-facing billboard, else an element
    // orb. The humanoid hides — and so does the companion copy of the
    // same navitar: he can't walk beside himself.
    const asNavitar = walkerKind === 'navitar' && !!companion;
    const navitarWalker = new THREE.Group();
    walkerRoot.add(navitarWalker);
    let navitarBillboard: THREE.Mesh | null = null;
    if (companion && asNavitar) {
      const nameLabel = makeTextSprite(companion.name);
      nameLabel.position.y = 2.0;
      navitarWalker.add(nameLabel);
      if (companion.modelUrl) {
        const loader = new GLTFLoader();
        loader.load(
          companion.modelUrl,
          gltf => {
            if (cancelled || !scene) return;
            const box = new THREE.Box3().setFromObject(gltf.scene);
            const size = box.getSize(new THREE.Vector3());
            const center = box.getCenter(new THREE.Vector3());
            const max = Math.max(size.x, size.y, size.z) || 1;
            const scale = (1.5 * (companion.modelZoom ?? 1)) / max;
            gltf.scene.scale.setScalar(scale);
            // Ground on the bounding box's min.y — feet ON the
            // ground plane, exactly like the battle stage loader.
            // (This loader used to centre the box on the origin,
            // which sank the model half a body into the floor —
            // Eddie's phone check, 2026-11-14.)
            gltf.scene.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);
            nameLabel.position.y = size.y * scale + 0.35;
            mountEl.dataset.walkerRender = 'model';
            navitarWalker.add(gltf.scene);
          },
          undefined,
          (err: unknown) => {
            if (cancelled) return;
            handleModelError('walker', companion.modelUrl ?? '', err);
          }
        );
      } else {
        mountEl.dataset.walkerRender = 'billboard-nomodel';
        addNavitarBillboard();
      }
    }
    function addNavitarBillboard() {
      if (!companion || !scene) return;
      if (companion.imageUrl) {
        const texture = new THREE.TextureLoader().load(companion.imageUrl);
        texture.colorSpace = THREE.SRGBColorSpace;
        const mat = new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          side: THREE.DoubleSide,
        });
        navitarBillboard = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 1.5), mat);
        navitarBillboard.position.y = 0.95;
        navitarWalker.add(navitarBillboard);
      } else {
        const orb = new THREE.Mesh(
          new THREE.SphereGeometry(0.4, 16, 12),
          new THREE.MeshStandardMaterial({
            color: new THREE.Color(ELEMENT_COLORS[companion.element] ?? '#2196F3'),
            emissive: new THREE.Color(ELEMENT_COLORS[companion.element] ?? '#2196F3'),
            emissiveIntensity: 0.7,
            roughness: 0.4,
          })
        );
        orb.position.y = 0.9;
        navitarWalker.add(orb);
      }
    }
    walker.visible = !asNavitar;
    navitarWalker.visible = asNavitar;

    // ---------- The companion: the player's navitar, a step to the side
    // and slightly behind the walker. GLB when it has one, 2D art on a
    // billboard plane when it doesn't, an element-coloured orb when it
    // has neither. The group follows the walker; the GLB load is async
    // and falls back gracefully if it fails.
    const companionGroup = new THREE.Group();
    companionGroup.visible = !asNavitar;
    scene.add(companionGroup);
    let companionBillboard: THREE.Mesh | null = null;
    const placeCompanion = (heading: number, walkerPos: THREE.Vector3) => {
      const fx = Math.sin(heading);
      const fz = Math.cos(heading);
      const rx = Math.cos(heading);
      const rz = -Math.sin(heading);
      companionGroup.position.set(
        walkerPos.x + rx * 0.95 - fx * 0.35,
        walkerPos.y,
        walkerPos.z + rz * 0.95 - fz * 0.35
      );
      companionGroup.rotation.y = heading;
    };
    const companionTarget = 1.15;
    // When the player walks AS their navitar, the companion copy is
    // hidden by design ("he can't walk beside himself") — so its
    // GLB is NOT loaded at all. Loading the same 13–25 MB model a
    // second time for an invisible copy doubled the fetch + parse
    // memory peak, which is exactly what makes a big GLB fail on a
    // phone browser (Eddie's phone check, 2026-11-14: the walker
    // came up as a 2D card while the same model loaded fine in
    // battle, where it loads once).
    if (companion && !asNavitar) {
      if (companion.modelUrl) {
        const loader = new GLTFLoader();
        loader.load(
          companion.modelUrl,
          gltf => {
            if (cancelled || !scene) return;
            const box = new THREE.Box3().setFromObject(gltf.scene);
            const size = box.getSize(new THREE.Vector3());
            const center = box.getCenter(new THREE.Vector3());
            const max = Math.max(size.x, size.y, size.z) || 1;
            const scale = (companionTarget * (companion.modelZoom ?? 1)) / max;
            gltf.scene.scale.setScalar(scale);
            // Ground on min.y, like the walker + the battle stage
            // (was: centred on the box, feet half a body under the
            // ground plane).
            gltf.scene.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);
            mountEl.dataset.companionRender = 'model';
            companionGroup.add(gltf.scene);
          },
          undefined,
          (err: unknown) => {
            if (cancelled) return;
            handleModelError('companion', companion.modelUrl ?? '', err);
          }
        );
      } else {
        mountEl.dataset.companionRender = 'billboard-nomodel';
        addBillboardFallback();
      }
    }
    function addBillboardFallback() {
      if (!companion || !scene) return;
      if (companion.imageUrl) {
        const texture = new THREE.TextureLoader().load(companion.imageUrl);
        texture.colorSpace = THREE.SRGBColorSpace;
        const mat = new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          side: THREE.DoubleSide,
        });
        companionBillboard = new THREE.Mesh(new THREE.PlaneGeometry(1.25, 1.25), mat);
        companionBillboard.position.y = 0.85;
        companionGroup.add(companionBillboard);
      } else {
        const orb = new THREE.Mesh(
          new THREE.SphereGeometry(0.35, 16, 12),
          new THREE.MeshStandardMaterial({
            color: new THREE.Color(ELEMENT_COLORS[companion.element] ?? '#2196F3'),
            emissive: new THREE.Color(ELEMENT_COLORS[companion.element] ?? '#2196F3'),
            emissiveIntensity: 0.7,
            roughness: 0.4,
          })
        );
        orb.position.y = 0.85;
        companionGroup.add(orb);
      }
    }
    // ---------- Model-load honesty (Eddie phone check, 2026-11-14)
    // A GLB that fails to load must never fail SILENTLY into the 2D
    // billboard: the failure is logged, marked on the mount dataset
    // (walkerRender / companionRender = 'model-error'), and in AR —
    // where a card is never allowed — the billboard is suppressed
    // and the page is told, so it shows the honest no-model panel.
    let walkerModelFailed = false;
    let companionModelFailed = false;
    function handleModelError(role: 'walker' | 'companion', url: string, err: unknown) {
      if (role === 'walker') walkerModelFailed = true;
      else companionModelFailed = true;
      console.warn(
        `[StrollScene] ${role} model failed to load: ${url} — ${
          arOn
            ? 'AR never shows a card; surfacing the honest no-model state.'
            : 'using the portrait billboard for this stroll (map mode only).'
        }`,
        err
      );
      mountEl.dataset[role === 'walker' ? 'walkerRender' : 'companionRender'] = 'model-error';
      if (arOn) {
        if (navitarBillboard) navitarBillboard.visible = false;
        if (companionBillboard) companionBillboard.visible = false;
        errCbRef.current?.();
      } else if (role === 'walker') {
        addNavitarBillboard();
      } else {
        addBillboardFallback();
      }
    }
    placeCompanion(Math.PI, walkerRoot.position);

    // ---------- Environment switching (no rebuild) ----------
    const applyEnvironment = (env: StrollEnvironment) => {
      if (!scene || !forest || !city || !hemi || !sun) return;
      // In AR the scenery stays hidden and the background stays
      // transparent whatever the environment toggle says; the
      // lighting still follows the environment.
      if (env === 'forest') {
        forest.visible = !arOn;
        city.visible = false;
        if (!arOn) {
          scene.background = new THREE.Color(0xaac4d6);
          scene.fog = new THREE.Fog(0xcfe0d8, 26, 120);
        }
        hemi.color.set(0xbfdcff);
        hemi.groundColor.set(0x3f6b4a);
        hemi.intensity = 0.9;
        sun.color.set(0xfff2d9);
        sun.intensity = 1.6;
        sun.position.set(8, 14, 6);
      } else {
        forest.visible = false;
        city.visible = !arOn;
        if (!arOn) {
          scene.background = new THREE.Color(0x35324a);
          scene.fog = new THREE.Fog(0x35324a, 26, 120);
        }
        hemi.color.set(0x6a6a9a);
        hemi.groundColor.set(0x2a2a33);
        hemi.intensity = 0.5;
        sun.color.set(0xff9a5c);
        sun.intensity = 0.5;
        sun.position.set(-6, 8, -4);
      }
    };
    // ---------- AR mode (Step 6) ----------
    // A soft contact shadow grounds the companion in the camera
    // view (there is no floor in AR). It tracks the walker on the
    // ground plane and only shows while AR is on.
    const arShadow = new THREE.Mesh(
      new THREE.CircleGeometry(0.95, 24),
      new THREE.MeshBasicMaterial({
        color: 0x000000,
        transparent: true,
        opacity: 0.32,
        depthWrite: false,
      })
    );
    arShadow.rotation.x = -Math.PI / 2;
    arShadow.position.set(0, 0.02, 8);
    arShadow.visible = false;
    scene.add(arShadow);
    let arOn = false;
    const applyArMode = (on: boolean) => {
      if (!scene || !renderer) return;
      arOn = on;
      if (on && (walkerModelFailed || companionModelFailed)) {
        // AR never shows a card: a model that failed to load keeps
        // its billboard hidden here and the page shows the honest
        // no-model panel instead.
        if (navitarBillboard) navitarBillboard.visible = false;
        if (companionBillboard) companionBillboard.visible = false;
        errCbRef.current?.();
      }
      if (!on) {
        if (navitarBillboard) navitarBillboard.visible = true;
        if (companionBillboard) companionBillboard.visible = true;
      }
      arShadow.visible = on;
      if (forest) forest.visible = on ? false : environment === 'forest';
      if (city) city.visible = on ? false : environment === 'city';
      if (on) {
        scene.background = null;
        scene.fog = null;
      } else {
        applyEnvironment(environment);
      }
    };
    // Swapping outfits never rebuilds the scene: it re-colours the
    // top and pants materials and rebuilds the hat slot.
    const applyOutfit = (o: AvatarOutfit) => {
      topMat.color.set(o.topColor);
      pantsMat.color.set(o.pantsColor);
      buildHat(o);
    };
    // ---------- Wild encounter rendering (Round 13) ----------
    // The popped-up creature: its real GLB, box-grounded like every
    // stroll model, standing on an element-coloured ring a few
    // steps ahead of the walker and facing it. Entrance is a
    // scale pop (ease-out-back, driven in the tick); the idle is
    // the standing yaw sway of the model presentation law — the
    // GLBs are static, so nothing here pretends to be rigged
    // animation. A failed GLB load marks the mount dataset and
    // leaves the ring standing alone for a beat is NOT acceptable —
    // no fake creature: the whole group comes down and the page's
    // card (real portrait art) carries the encounter.
    let encounterGroup: THREE.Group | null = null;
    let encounterPopStart = 0;
    let encounterFaceYaw = 0;
    const disposeEncounterGroup = (g: THREE.Group) => {
      g.traverse(obj => {
        const mesh = obj as THREE.Mesh;
        if (mesh.geometry) mesh.geometry.dispose();
        const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
        const mats = Array.isArray(material) ? material : material ? [material] : [];
        mats.forEach(m => {
          const withMap = m as THREE.MeshBasicMaterial;
          if (withMap.map) withMap.map.dispose();
          m.dispose();
        });
      });
    };
    const applyEncounter = (wild: StrollWildEncounter | null) => {
      if (!scene) return;
      if (encounterGroup) {
        scene.remove(encounterGroup);
        disposeEncounterGroup(encounterGroup);
        encounterGroup = null;
      }
      delete mountEl.dataset.encounterRender;
      delete mountEl.dataset.encounterName;
      delete mountEl.dataset.encounterPos;
      if (encounterPosRef) encounterPosRef.current = null;
      if (!wild) return;
      // A few steps ahead of wherever the walker is facing, kept
      // inside the world bound — the creature stands its ground
      // there; the player walks to it (or doesn't).
      const headingNow = walkerRoot.rotation.y;
      const px = Math.max(
        -BOUND + 2,
        Math.min(BOUND - 2, walkerRoot.position.x + Math.sin(headingNow) * 6.5)
      );
      const pz = Math.max(
        -BOUND + 2,
        Math.min(BOUND - 2, walkerRoot.position.z + Math.cos(headingNow) * 6.5)
      );
      const group = new THREE.Group();
      group.position.set(px, 0, pz);
      encounterFaceYaw = Math.atan2(walkerRoot.position.x - px, walkerRoot.position.z - pz);
      group.rotation.y = encounterFaceYaw;
      group.scale.setScalar(0.001);
      const ring = new THREE.Mesh(
        new THREE.CircleGeometry(1.15, 28),
        new THREE.MeshBasicMaterial({
          color: new THREE.Color(ELEMENT_COLORS[wild.element] ?? '#ffffff'),
          transparent: true,
          opacity: 0.4,
          depthWrite: false,
        })
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = 0.03;
      group.add(ring);
      scene.add(group);
      encounterGroup = group;
      encounterPopStart = performance.now();
      mountEl.dataset.encounterName = wild.name;
      mountEl.dataset.encounterPos = `${px.toFixed(2)},${pz.toFixed(2)}`;
      if (encounterPosRef) encounterPosRef.current = { x: px, z: pz };
      const loader = new GLTFLoader();
      loader.load(
        wild.modelUrl,
        gltf => {
          if (cancelled || encounterGroup !== group || !scene) return;
          const box = new THREE.Box3().setFromObject(gltf.scene);
          const size = box.getSize(new THREE.Vector3());
          const center = box.getCenter(new THREE.Vector3());
          const max = Math.max(size.x, size.y, size.z) || 1;
          // A touch larger than the companion's 1.15 presence — a
          // wild thing should read as an event, not a pet.
          const scale = (1.35 * (wild.modelZoom ?? 1)) / max;
          gltf.scene.scale.setScalar(scale);
          // Ground on min.y, like the walker/companion loaders.
          gltf.scene.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);
          if (wild.modelRotationY) gltf.scene.rotation.y = wild.modelRotationY;
          group.add(gltf.scene);
          const label = makeTextSprite(wild.name);
          label.position.y = size.y * scale + 0.4;
          group.add(label);
          mountEl.dataset.encounterRender = 'model';
        },
        undefined,
        (err: unknown) => {
          if (cancelled || encounterGroup !== group) return;
          console.warn(
            `[StrollScene] wild encounter model failed to load: ${wild.modelUrl} — no fake creature stands in the scene; the encounter card carries the portrait.`,
            err
          );
          mountEl.dataset.encounterRender = 'model-error';
          if (scene) scene.remove(group);
          disposeEncounterGroup(group);
          encounterGroup = null;
        }
      );
    };
    apiRef.current = {
      setEnvironment: applyEnvironment,
      setOutfit: applyOutfit,
      setArMode: applyArMode,
      setEncounter: applyEncounter,
    };
    applyEnvironment(environment);
    applyOutfit(outfit);
    applyArMode(arMode);
    applyEncounter(encounterPropRef.current);

    // ---------- Input: WASD / arrows, plus drag-to-look ----------
    const keys = { forward: false, left: false, right: false, back: false };
    // Typing guard (Round 33.5): keystrokes aimed at a form field
    // are the field's, never the walker's — without this, the
    // WASD handler's preventDefault eats the letters w/a/s/d out
    // of any text typed on the page (the compass pin-name field
    // is Stroll's first: "My car" came out "My cr"). Gameplay
    // keys are untouched whenever the player isn't typing.
    const fromFormField = (e: KeyboardEvent): boolean => {
      const t = e.target as HTMLElement | null;
      if (!t) return false;
      const tag = t.tagName;
      return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || t.isContentEditable;
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (fromFormField(e)) return;
      if (e.key === 'w' || e.key === 'W' || e.key === 'ArrowUp') {
        keys.forward = true;
        e.preventDefault();
      } else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowDown') {
        keys.back = true;
        e.preventDefault();
      } else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') {
        keys.left = true;
        e.preventDefault();
      } else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') {
        keys.right = true;
        e.preventDefault();
      }
    };
    const onKeyUp = (e: KeyboardEvent) => {
      // Keyups always clear, wherever they land: a key released
      // while a field has focus must never leave the walker
      // walking on its own.
      if (e.key === 'w' || e.key === 'W' || e.key === 'ArrowUp') keys.forward = false;
      else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowDown') keys.back = false;
      else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') keys.left = false;
      else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') keys.right = false;
    };
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);

    let dragging = false;
    let lastPointerX = 0;
    let camYaw = Math.PI + Math.PI; // behind the walker (heading starts at PI)
    const onPointerDown = (e: PointerEvent) => {
      dragging = true;
      lastPointerX = e.clientX;
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!dragging) return;
      camYaw -= (e.clientX - lastPointerX) * 0.005;
      lastPointerX = e.clientX;
    };
    const onPointerUp = () => {
      dragging = false;
    };
    renderer.domElement.addEventListener('pointerdown', onPointerDown);
    renderer.domElement.addEventListener('pointermove', onPointerMove);
    renderer.domElement.addEventListener('pointerup', onPointerUp);
    renderer.domElement.addEventListener('pointercancel', onPointerUp);
    renderer.domElement.addEventListener('pointerleave', onPointerUp);

    const onResize = () => {
      if (!mount || !renderer || !camera) return;
      const w = mount.clientWidth;
      const h = Math.max(mount.clientHeight, 1);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener('resize', onResize);

    // ---------- Walk loop ----------
    let heading = Math.PI;
    let walkPhase = 0;
    let lastTick = performance.now();
    // Walk-training distance (Round 9): the walker's accumulated
    // real travel this scene mount, and the last position it was
    // measured from. See the accumulation in the tick.
    let distLastX: number | null = null;
    let distLastZ: number | null = null;
    let distTotal = 0;
    // Walker-position instrumentation (same dataset pattern as
    // walkerRender/companionRender): the live world position,
    // written every frame so checks can measure real travel
    // (glide drives included) instead of trusting pixels.
    const tick = () => {
      if (cancelled) return;
      raf = requestAnimationFrame(tick);
      const now = performance.now();
      const dt = Math.min((now - lastTick) / 1000, 0.05);
      lastTick = now;

      // Keyboard only since Round 9: the on-screen walk buttons
      // were removed on Eddie's order (the thumb glide superseded
      // them), so the touch-flag merge that fed these is gone —
      // WASD/arrows on the window listener below are the keys.
      const fwd = keys.forward;
      const back = keys.back;
      const left = keys.left;
      const right = keys.right;
      if (!arOn) {
        if (left) heading += TURN_SPEED * dt;
        if (right) heading -= TURN_SPEED * dt;
      } else {
        // AR: the companion always faces the camera (heading 0 =
        // model front toward +z, where the phone is).
        heading = 0;
      }
      // Desired displacement this frame. Manual input always wins;
      // the "Walk with me" GPS target steers only while no manual
      // key is held (manual is the override). GPS movement is
      // cosmetic: it moves the walker and nothing else.
      let mx = 0;
      let mz = 0;
      const manualSpeed = fwd ? WALK_SPEED : back ? -WALK_SPEED * 0.5 : 0;
      if (arOn) {
        // AR movement is frame-relative: forward walks AWAY from
        // the camera (farther = smaller), back comes nearer, and
        // left/right sidestep across the frame.
        if (fwd) mz -= WALK_SPEED * dt;
        if (back) mz += WALK_SPEED * 0.6 * dt;
        if (left) mx -= WALK_SPEED * 0.7 * dt;
        if (right) mx += WALK_SPEED * 0.7 * dt;
      } else if (manualSpeed !== 0) {
        mx = Math.sin(heading) * manualSpeed * dt;
        mz = Math.cos(heading) * manualSpeed * dt;
      }
      // THUMB GLIDE (Round 8): a manual input class of its own —
      // the keys outrank it, it outranks the GPS target.
      // Outside AR the direction is CAMERA-relative (glide up =
      // walk away from the camera, glide right = walk to the
      // camera's right) and the walker turns toward the travel
      // direction as it goes; in AR it is frame-relative like the
      // keys (up = farther away, down = nearer).
      const glide = glideRef.current;
      const glideActive = !!glide && (Math.abs(glide.x) > 0.12 || Math.abs(glide.y) > 0.12);
      if (glideActive && glide) {
        if (arOn) {
          if (!fwd && !back && !left && !right) {
            mx = glide.x * WALK_SPEED * 0.7 * dt;
            mz = glide.y * WALK_SPEED * dt;
          }
        } else if (manualSpeed === 0 && !left && !right) {
          const fx = -Math.sin(camYaw);
          const fz = -Math.cos(camYaw);
          const rx = Math.cos(camYaw);
          const rz = -Math.sin(camYaw);
          let dx = rx * glide.x + fx * -glide.y;
          let dz = rz * glide.x + fz * -glide.y;
          const len = Math.hypot(dx, dz) || 1;
          const mag = Math.min(1, len);
          dx /= len;
          dz /= len;
          const bearing = Math.atan2(dx, dz);
          let diff = bearing - heading;
          while (diff > Math.PI) diff -= Math.PI * 2;
          while (diff < -Math.PI) diff += Math.PI * 2;
          heading += Math.max(-TURN_SPEED * dt, Math.min(TURN_SPEED * dt, diff));
          mx = dx * WALK_SPEED * mag * dt;
          mz = dz * WALK_SPEED * mag * dt;
        }
      }
      let gpsMoving = false;
      const gps = gpsTarget.current;
      if (!arOn && manualSpeed === 0 && !left && !right && !glideActive && gps) {
        const dx = gps.x - walkerRoot.position.x;
        const dz = gps.z - walkerRoot.position.z;
        const dist = Math.hypot(dx, dz);
        if (dist > 0.2) {
          const bearing = Math.atan2(dx, dz);
          let diff = bearing - heading;
          while (diff > Math.PI) diff -= Math.PI * 2;
          while (diff < -Math.PI) diff += Math.PI * 2;
          heading += Math.max(-TURN_SPEED * dt, Math.min(TURN_SPEED * dt, diff));
          const step = Math.min(dist, WALK_SPEED * 1.15 * dt);
          mx = (dx / dist) * step;
          mz = (dz / dist) * step;
          gpsMoving = true;
        }
      }
      const moving = mx !== 0 || mz !== 0 || gpsMoving;
      if (mx !== 0 || mz !== 0) {
        if (arOn) {
          // The AR frame is small: the companion stays in view —
          // a few steps left/right, a few nearer/farther.
          walkerRoot.position.x = Math.max(-3.4, Math.min(3.4, walkerRoot.position.x + mx));
          walkerRoot.position.z = Math.max(5.0, Math.min(11.0, walkerRoot.position.z + mz));
        } else {
          // Soft edge: past SOFT_BOUND the world resists progressively
          // (down to a crawl at BOUND) while the fog hides the rim.
          const cheb = Math.max(Math.abs(walkerRoot.position.x), Math.abs(walkerRoot.position.z));
          const edge =
            cheb <= SOFT_BOUND
              ? 1
              : Math.max(0.12, 1 - ((cheb - SOFT_BOUND) / (BOUND - SOFT_BOUND)) * 0.88);
          walkerRoot.position.x = Math.max(
            -BOUND,
            Math.min(BOUND, walkerRoot.position.x + mx * edge)
          );
          walkerRoot.position.z = Math.max(
            -BOUND,
            Math.min(BOUND, walkerRoot.position.z + mz * edge)
          );
        }
      }
      walkerRoot.rotation.y = heading;
      // Written every frame: under software rendering the frame
      // rate can drop to a few fps, and a throttled write would
      // report seconds-old positions to movement checks.
      mountEl.dataset.walkerPos = `${walkerRoot.position.x.toFixed(2)},${walkerRoot.position.z.toFixed(2)}`;
      // Stroll compass (Round 33.5): the same pose in ref form for
      // the page's compass interval — read-only there, never
      // persisted, never leaves the device.
      if (walkerRef) {
        walkerRef.current = {
          x: walkerRoot.position.x,
          z: walkerRoot.position.z,
          heading,
        };
      }
      // Walk-training distance (Round 9): accumulate the walker's
      // REAL stepped travel. Every movement source (keys, glide,
      // GPS steering) moves the walker in capped per-frame steps
      // (≤ WALK_SPEED×1.15×dt, dt clamped to 0.05 — under 0.25
      // units a frame), so frame deltas are honest by construction;
      // the 1-unit cap is a sanity belt — a bigger one-frame jump
      // can only be a discontinuity, never travel, and standing
      // still accumulates exactly nothing.
      if (distLastX === null || distLastZ === null) {
        distLastX = walkerRoot.position.x;
        distLastZ = walkerRoot.position.z;
      } else {
        const stepDelta = Math.hypot(
          walkerRoot.position.x - distLastX,
          walkerRoot.position.z - distLastZ
        );
        if (stepDelta > 0 && stepDelta <= 1) distTotal += stepDelta;
        distLastX = walkerRoot.position.x;
        distLastZ = walkerRoot.position.z;
        if (distanceRef) distanceRef.current = distTotal;
      }
      // The stroll GLBs are grounded on their bounding-box min.y
      // (see the loaders), so the walker root stays ON the ground
      // plane in both modes — no compensating lift. In AR the
      // contact shadow at y=0.02 is the model's true contact line.
      const baseY = 0;
      if (moving) {
        walkPhase += dt * 10;
        const bob = Math.abs(Math.sin(walkPhase)) * 0.06;
        walkerRoot.position.y = baseY + bob;
        leftLeg.rotation.x = Math.sin(walkPhase) * 0.55;
        rightLeg.rotation.x = -Math.sin(walkPhase) * 0.55;
        leftArm.rotation.x = -Math.sin(walkPhase) * 0.45;
        rightArm.rotation.x = Math.sin(walkPhase) * 0.45;
        companionGroup.position.y = Math.abs(Math.sin(walkPhase + 1.2)) * 0.06;
      } else {
        walkerRoot.position.y = baseY;
        leftLeg.rotation.x = 0;
        rightLeg.rotation.x = 0;
        leftArm.rotation.x = 0;
        rightArm.rotation.x = 0;
        companionGroup.position.y = 0;
      }
      placeCompanion(heading, walkerRoot.position);
      // Wild encounter (Round 13): the pop-in — an ease-out-back
      // scale over ~0.55s with a small overshoot — settling into
      // the standing yaw sway (±~10°) of the presentation law.
      if (encounterGroup) {
        const t = Math.min(1, (now - encounterPopStart) / 550);
        const c1 = 1.70158;
        const c3 = c1 + 1;
        const ease = 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
        encounterGroup.scale.setScalar(Math.max(0.001, ease));
        encounterGroup.rotation.y = encounterFaceYaw + Math.sin(now * 0.0016) * 0.18;
      }
      if (companionBillboard && camera) {
        companionBillboard.quaternion.copy(camera.quaternion);
      }
      if (navitarBillboard && camera) {
        navitarBillboard.quaternion.copy(camera.quaternion);
      }

      // Camera: in AR it is the phone — fixed, with a gentle
      // device-orientation parallax; the companion moves inside
      // its frame. Outside AR, the follow camera sits behind the
      // walker, easing back after a drag.
      if (camera) {
        if (arOn) {
          arShadow.position.set(walkerRoot.position.x, 0.02, walkerRoot.position.z);
          camera.position.set(parallax.current.x * 0.6, 1.5 + parallax.current.y * 0.35, 14.6);
          camera.lookAt(walkerRoot.position.x * 0.55, 0.8, walkerRoot.position.z);
        } else {
          const behind = heading + Math.PI;
          if (!dragging) {
            let diff = behind - camYaw;
            while (diff > Math.PI) diff -= Math.PI * 2;
            while (diff < -Math.PI) diff += Math.PI * 2;
            camYaw += diff * Math.min(1, dt * 1.2);
          }
          camera.position.set(
            walkerRoot.position.x + Math.sin(camYaw) * 6.5,
            3.4,
            walkerRoot.position.z + Math.cos(camYaw) * 6.5
          );
          camera.lookAt(walkerRoot.position.x, 1.1, walkerRoot.position.z);
        }
        // Idle sleep (Round 36.9 Part 7e): while the app
        // sleeps the Stroll scene skips its render — the
        // frozen frame stands until the first touch wakes it.
        if (renderer && scene && !isAppIdle()) renderer.render(scene, camera);
      }
    };
    tick();

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      renderer.domElement.removeEventListener('pointerdown', onPointerDown);
      renderer.domElement.removeEventListener('pointermove', onPointerMove);
      renderer.domElement.removeEventListener('pointerup', onPointerUp);
      renderer.domElement.removeEventListener('pointercancel', onPointerUp);
      renderer.domElement.removeEventListener('pointerleave', onPointerUp);
      if (scene) {
        scene.traverse(obj => {
          const mesh = obj as THREE.Mesh;
          if (mesh.geometry) mesh.geometry.dispose();
          const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
          if (Array.isArray(material)) material.forEach(m => m.dispose());
          else if (material) material.dispose();
        });
      }
      renderer?.dispose();
      // Round 36.30 rider: actually RELEASE the WebGL context,
      // the way ModelCanvas has since Round 6 and the battle
      // arena since Round 36.29. dispose() alone leaves the
      // context — and every GPU texture it uploaded — alive
      // until the browser's lazy GC, and this scene rebuilds
      // whenever the walker/companion changes (sceneKey), so
      // each rebuild used to leave one more context resident.
      // On a phone with a small live-context cap that is the
      // same slow leak 36.29 measured in the arena. Losing the
      // context here frees its GPU resources immediately; the
      // next scene build creates a fresh one. This component
      // registers no contextlost handler, so nothing can
      // mis-fire mid-teardown.
      renderer?.forceContextLoss();
      if (renderer && mount.contains(renderer.domElement)) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, [sceneKey]);

  return <div ref={mountRef} style={{ width: '100%', height: '100%', cursor: 'grab' }} />;
};

export default StrollScene;
